INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('longest-plateau', 7, NULL, 'def gen():
    _s = [1274851374]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    V = 1000000000
    RUN = 20
    N = 200000
    a = []
    while len(a) < N:
        v = r(-V, V)
        a.extend([v] * r(1, RUN))
    a = a[:N]
    return f"{N}\n{'' ''.join(map(str, a))}\n"
', '20 -997248150', 0);
